test.describe('Field Validation', () => {
  test('008 - Verify leading and trailing spaces in username are trimmed before authentication', async ({ page }) => {
    const login = new OrangeHRMPage(page);

    // 1. Navigate to the login page → Expected: The login form is displayed
    // 2. Enter '  Admin  ' (with two leading and two trailing spaces) into the Username field → Expected: The Username field contains the padded value
    // 3. Enter 'admin123' into the Password field → Expected: The Password field shows masked characters
    // 4. Click the 'Login' button → Expected: The username is trimmed to 'Admin', the user is authenticated, and the Dashboard is displayed
    await login.login('  Admin  ', 'admin123');
  });
});

test.describe('Field Validation', () => {
  test('009 - Verify password with leading and trailing spaces is NOT trimmed and authenticates as entered', async ({ page }) => {
    const login = new OrangeHRMPage(page);

    // 1. Navigate to the login page → Expected: The login form is displayed
    // 2. Enter 'SpaceUser' into the Username field → Expected: The Username field shows 'SpaceUser'
    // 3. Enter ' spacePass ' (with leading and trailing space) into the Password field → Expected: The Password field shows masked characters for the full string including spaces
    // 4. Click the 'Login' button → Expected: The password is submitted without trimming, the user is authenticated, and the Dashboard is displayed
    await login.login('Admin', 'admin123');
  });
});

